1. // Copyright(c) The Maintainers of Nanvix.
2. // Licensed under the MIT License.
3. 
4. //! Kernel frame type.
5. //!
6. //! A [`KernelFrame`] represents a single page-sized physical frame allocated for kernel use.
7. //! It provides `Deref`/`DerefMut` for direct kernel access (identity-mapped) and frees the
8. //! underlying frame on drop via the global frame allocator.
9. 
10. //==================================================================================================
11. // Imports
12. //==================================================================================================
13. 
14. use crate::hal::mem::{
15.     Address,
16.     FrameAddress,
17.     PageAligned,
18.     PhysicalAddress,
19. };
20. use ::arch::mem;
21. use ::core::ops::{
22.     Deref,
23.     DerefMut,
24. };
25. use ::sys::error::Error;
26. use ::vstd::prelude::*;
27. 
28. //==================================================================================================
29. // Kernel Frame
30. //==================================================================================================
31. 
32. /// A type that represents a kernel frame.
33. #[derive(Debug)]
34. #[verus_verify]
35. pub struct KernelFrame {
36.     /// Frame address.
37.     base: FrameAddress,
38. }
39. 
40. #[cfg(verus_keep_ghost)]
41. verus! {
42. 
43. /// Abstract view of a [`KernelFrame`]: the base physical address of the frame it
44. /// owns. Lets allocator contracts name a returned kernel frame's address (e.g.
45. /// the contiguity guarantee of `alloc_many_kernel_frames`) without exposing any
46. /// storage detail.
47. impl View for KernelFrame {
48.     type V = int;
49. 
50.     closed spec fn view(&self) -> int {
51.         self.base@
52.     }
53. }
54. 
55. } // verus!
56. 
57. impl KernelFrame {
58.     ///
59.     /// # Description
60.     ///
61.     /// Instantiates a kernel frame.
62.     ///
63.     /// # Parameters
64.     ///
65.     /// - `base`: Frame address.
66.     ///
67.     /// # Returns
68.     ///
69.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
70.     ///
71.     pub(super) fn new(base: FrameAddress) -> Result<Self, Error> {
72.         // Ensure the frame is identity-mapped in the kernel address space so that
73.         // Deref/DerefMut can safely access it. This lazily installs a page
74.         // table entry if needed (page tables come from a BSS pool, so no recursive frame
75.         // allocation occurs).
76.         let phys_addr: PageAligned<PhysicalAddress> =
77.             PageAligned::from_raw_value(base.into_raw_value()).map_err(|e| {
78.                 error!("frame base is not page-aligned: {e:?}");
79.                 e
80.             })?;
81.         crate::mm::virt::identity_map_page(phys_addr).map_err(|e| {
82.             error!("failed to identity-map frame: {:?}", e);
83.             e
84.         })?;
85. 
86.         Ok(Self { base })
87.     }
88. 
89.     ///
90.     /// # Description
91.     ///
92.     /// Returns the base address of the target kernel frame.
93.     ///
94.     /// # Returns
95.     ///
96.     /// The base address of the target kernel frame.
97.     ///
98.     pub fn base(&self) -> FrameAddress {
99.         self.base
100.     }
101. 
102.     ///
103.     /// # Description
104.     ///
105.     /// Clears the target kernel frame.
106.     ///
107.     /// Uses the identity-map `memset` backend so that the write runs in the kernel address space.
108.     /// This avoids a page fault when the current CR3 points to a user page directory that lacks
109.     /// the PDE for this frame's physical address.
110.     ///
111.     pub fn clear(&mut self) -> Result<(), Error> {
112.         let base: *mut u8 = self.base.into_raw_value() as *mut u8;
113.         crate::mm::virt::memset(base, 0, mem::PAGE_SIZE).map_err(|e| {
114.             error!("memset failed: {:?}", e);
115.             e
116.         })
117.     }
118. }
119. 
120. /// # Safety
121. ///
122. /// `Deref` accesses the identity-mapped frame directly. The caller must ensure that the current
123. /// CR3 points to a page directory that has the relevant PDE for this frame's physical address
124. /// (i.e., the kernel page directory, or a user page directory into which the PDE has been
125. /// propagated via [`sync_kernel_pdes`](crate::mm::virt::sync_kernel_pdes)). For CR3-agnostic
126. /// writes, prefer [`KernelFrame::clear()`] which uses the identity-map `memset` backend.
127. impl Deref for KernelFrame {
128.     type Target = [u8];
129. 
130.     fn deref(&self) -> &Self::Target {
131.         let ptr: usize = self.base.into_raw_value();
132.         unsafe { core::slice::from_raw_parts(ptr as *const u8, mem::PAGE_SIZE) }
133.     }
134. }
135. 
136. /// # Safety
137. ///
138. /// See [`Deref`] impl — the same CR3 invariant applies.
139. impl DerefMut for KernelFrame {
140.     fn deref_mut(&mut self) -> &mut Self::Target {
141.         let ptr: usize = self.base.into_raw_value();
142.         unsafe { core::slice::from_raw_parts_mut(ptr as *mut u8, mem::PAGE_SIZE) }
143.     }
144. }
145. 
